        # Check if 1 is a prime number
        if a == 1:
            return False
        # Check if a is prime number by checking if all numbers from 2 to sqrt(a) are prime
        for i in range(2, int(a**0.5) + 1):
            if a % i == 0:
                return False
        # Check if the prime factor of a is a multiple of 3
        for i in range(2, a):
            if a % i == 0:
                if i == 3:
                    return True
                if a % i == 0:
                    return False
        return True
    else:
        return False

