def move_one_ball(arr):
    # Check if the array is empty
    if not arr:
        return True

    # Check if the array has only one element
    if len(arr) == 1:
        return True

    # Check if the first element is greater than the last element
    if arr[0] > arr[-1]:
        return False

    # Check if the array can be sorted by performing right shifts
    for i in range(1, len(arr) - 1):
        if arr[i] > arr[i + 1]:
            arr[1 : i + 1] = [arr[i], arr[i + 1]]
            break  # Found the array in sorted order
    else:
        arr = [0] + arr + [0]  # Create a sorted array by appending zeros to the start and end

    # Check if the array can be sorted by performing right shifts
    if arr[0] > arr[1] and arr[1] > arr[2]:
        return True
    elif arr[-1] < arr[-2]:
        return True
    else:
        return False
